raw_prompt_json:
{
  "summary": "A sophisticated mobile-first admin dashboard for high-intensity operations, featuring a deep black background, vibrant orange highlights, glassmorphic overlays, and fluid animations. Optimized for touch interactions with large targets and real-time feedback loops.",
  "style": {
    "description": "The style is 'Neon-Brutalist Glassmorphism'. It relies on a pure black background (#000000) to make colors pop. Typography is centered around IBM Plex Sans Thai, utilizing heavy weights (700-900) for headers and wide-tracked uppercase labels for secondary information. The primary accent is a warm orange (#D97234). Interactive elements use 'ripple' effects and 300ms cubic-bezier transitions. Status-driven components feature animated glow borders (red for urgent, orange for billing) to draw immediate attention without visual clutter.",
    "prompt": "Create a high-contrast dark mode UI with a base background of #000000 and text in #FFFFFF. **Typography:** Use 'IBM Plex Sans Thai'. Headings should be bold (600-900) with tracking-tighter (-0.05em). Labels should be uppercase, tracking-widest (0.2em), and 10px-12px. **Colors:** Primary Accent: #D97234. Success: Green-500. Alert: Red-500. **Borders & Shapes:** All containers use rounded corners (24px to 40px). Use 1px borders with white/10 opacity. **Glassmorphism:** Apply `backdrop-blur: 20px` and `background: rgba(255,255,255, 0.05)` to sidebars and headers. **Animations:** Implement pulse animations for urgent states (`pulse-red` and `pulse-orange`) and slide-up fades for page transitions. **Shadows:** Use large, soft shadows for buttons using the accent color with 20-30% opacity (e.g., `shadow-[#D97234]/20`)."
  },
  "layout_and_structure": {
    "description": "A responsive dual-navigation layout. On desktop (lg), it features a 300px fixed sidebar. On mobile, the sidebar is hidden, and a 20-24px height compact header is paired with a fixed bottom navigation bar (h-20) for thumb-reachability. Content is housed in a vertically scrollable container with hidden scrollbars.",
    "prompts": [
      {
        "part": "Desktop Sidebar",
        "prompt": "Fixed 300px width sidebar. Background #000000 with a 1px right border (white/10). Includes a logo section with a 40x40px #D97234 rounded-2xl icon. Navigation items are h-56px, rounded-2xl, with active states using #D97234 background and white text. Bottom section contains a status card with a pulsing green indicator."
      },
      {
        "part": "Mobile Header",
        "prompt": "Sticky top bar, backdrop-blur-xl, bg-black/90. Height 60px on mobile, 80px on desktop. Left side shows page hierarchy in 10px uppercase breadcrumbs. Right side features a 40x40px notification bell with a red dot and a gradient profile avatar (#D97234 to orange-300)."
      },
      {
        "part": "Mobile Bottom Navigation",
        "prompt": "Fixed at screen bottom, h-20 (80px), bg-black/90. Flex-row layout with 5 equal buttons. Each button has a 24px icon and 8px uppercase text label. Active tab is colored #D97234 with a small dot indicator at the top center of the button."
      },
      {
        "part": "Feed System (Live Cards)",
        "prompt": "Vertical stack of cards. On mobile, cards have p-4; on desktop, p-8. Cards use white/5 background and rounded-32px. Urgent cards have a pulsing border (`@keyframes pulse { 0% { border-color: rgba(239, 68, 68, 0.3); } 50% { border-color: rgba(239, 68, 68, 0.8); } }`). Each card has a header with an icon and time-ago stamp, a main section with large tracking-tighter text (4xl to 6xl for numbers), and a full-width action button at the bottom."
      },
      {
        "part": "Catalogue Grid",
        "prompt": "Responsive grid: 1 col on mobile, 2 on tablet, 3 on desktop. Cards feature a 96x96px emoji/image container with a shadow-inner effect. Includes stock progress bars (h-2px) and a split-button footer for 'Hide' and 'Edit' actions."
      },
      {
        "part": "Stats & Insights",
        "prompt": "KPI grid using rounded-32px cards. Each card contains a top-row with a 48x48px icon and a growth percentage. Center features large numeric values (text-3xl). Bottom features a sparkline SVG (path stroke-width 2) representing trends."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Interactive Floor Map",
      "description": "A real-time grid of status-aware table tiles.",
      "prompt": "A grid of aspect-square tiles (min-w-60px). Tiles are rounded-32px. Background and border colors change based on status: Empty (white/5, border-white/10), Alert (bg-red-500/20, border-red-500), Billing (bg-orange-500/20, border-orange-500). Each tile has a center-aligned table number and a bottom-aligned status dot (pulsing for active alerts)."
    },
    {
      "component": "Floating Toast Notification",
      "description": "High-contrast floating pill with undo capabilities.",
      "prompt": "A fixed floating pill at bottom-32 (above mobile nav). Pure white background, black text, rounded-full. Includes a black circular icon on the left and an 'Undo' button with #D97234 hover state. Entry animation: translate-y-20 to 0 with opacity fade."
    },
    {
      "component": "Action Bottom Sheet",
      "description": "Mobile-only modal that slides up from the bottom.",
      "prompt": "A full-width modal with rounded-t-[40px] top corners. Background is pure black. Includes a sticky header with a close button and a scrollable form body. Primary action button at the bottom is fixed, large (h-64px), and uses the #D97234 theme with a subtle shadow-xl."
    }
  ]
}

{
  "summary": "A modern split-panel UI design for administration and configuration. The left side features a dynamic animated gradient with geometric overlays, while the right side focuses on a highly-elevated white card containing modular form sections with icon badges and taller, icon-inclusive inputs.",
  "style": {
    "description": "Modern geometric aesthetics using Plus Jakarta Sans (400-800 weight) for a tech-forward look. Color palette: Primary Brand Red (#e53935), Deep Red (#9b1c1c), and accent colors for categorization (Blue-100/600, Orange-100/600, Purple-100/600). The style emphasizes depth with a specific 0 4px 20px rgba(0,0,0,0.08) shadow and large 28px border radii for cards.",
    "prompt": "Apply a design system based on 'Plus Jakarta Sans'. Typography: Titles should be font-weight: 800 with tight tracking; body text in #1a1a1a. Color Palette: Primary #e53935, Background #f8fafc, Card White #ffffff. Elevation: Cards must have 28px border-radius and shadow '0 4px 20px rgba(0,0,0,0.08)'. Accents: Use categorical badges with 10% opacity backgrounds (Blue #3b82f6, Orange #f59e0b, Purple #8b5cf6). Buttons: Primary CTA at 56px height, background #e53935, with active:scale(0.98) micro-interaction. Inputs: 56px height, 12px border-radius, #f9fafb background, with left-aligned 20px icons and #e53935 focus borders. Visual effects: Glassmorphism for small badges (backdrop-filter: blur(12px), bg-white/10, border-white/20). Animations: Gradient-move 8s ease infinite for branding panels."
  },
  "layout_and_structure": {
    "description": "A responsive dual-panel layout. Mobile shows stacked panels; desktop features a fixed-width left information sidebar (400px-450px) and a centered content area with a modular card.",
    "prompts": [
      {
        "part": "Left Sidebar",
        "prompt": "Fixed-width sidebar (450px) with an animated linear-gradient background (from #e53935 to #9b1c1c). Overlay a repeating white geometric SVG pattern at 8% opacity. Content includes a top-aligned uppercase logo with 0.3em letter spacing, a central hero headline (text-4xl, font-extrabold), and a bottom-aligned glassmorphic version badge with a pulsing green status dot."
      },
      {
        "part": "Progress Indicator",
        "prompt": "Centered above the main card, a horizontal row of indicator dots. Current step is 10px diameter in #e53935; inactive steps are 8px diameter in #d1d5db. 8px spacing between dots."
      },
      {
        "part": "Main Configuration Card",
        "prompt": "A container with max-width 520px, 28px rounded corners, and 40px internal padding. Structure: Header with 30px font-size title, followed by vertical sections separated by 32px spacing. Each section starts with a circular icon badge (32px diameter) and a tracking-wide uppercase label."
      },
      {
        "part": "Sectional Groups",
        "prompt": "Group related inputs inside sections. For special permissions, use a full-width container with 20px padding, #faf5ff background (Purple-50), and a light border. Include a descriptive title, subtitle, and right-aligned iOS toggle switch."
      },
      {
        "part": "Selection Modal",
        "prompt": "Full-screen overlay with backdrop-blur(4px) and bg-black/40. Center a 500px wide white card with 24px border-radius. Features a sticky header with breadcrumb navigation and a footer with a primary/secondary button pair. Content area is a scrollable list of interactive items with 16px hover-scaling and border transitions."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Category Icon Badges",
      "description": "Circular icons used to label form sections.",
      "prompt": "32px x 32px circular containers. Credentials: bg-blue-100, text-blue-600. Folder: bg-orange-100, text-orange-600. Permissions: bg-purple-100, text-purple-600. Place centered 18px icons inside."
    },
    {
      "component": "iOS-Style Toggle",
      "description": "Smooth sliding switch for boolean inputs.",
      "prompt": "44px width, 24px height pill-shaped track. Default state: bg-gray-300. Active state: bg-[#e53935]. Inner circle: 20px diameter, white, 2px padding from edge, transitions with transform: translateX(100%) when checked."
    },
    {
      "component": "Success Field Indicator",
      "description": "Micro-interaction for validated inputs.",
      "prompt": "Position a 18px check-circle icon (#22c55e) absolutely at the right-center of input fields (right: 16px). Only show when input condition is met."
    }
  ],
  "special_notes": "MUST: Use 56px heights for all primary interactive elements (buttons, inputs) for touch-friendliness. MUST: Ensure the geometric pattern in the sidebar remains subtle (opacity < 0.1). MUST NOT: Use standard 4px or 8px border radii; the design relies on the soft look of 24px-28px curves. MUST: Include internal padding of at least 16px for all input fields to accommodate icons."
}

{
  "summary": "A clean, dark-themed mobile dashboard interface inspired by Notion's layout and border logic, featuring a 2-column utility grid and callout-style banners for services like credits, data, and referral programs.",
  "style": {
    "description": "The style is defined by a low-contrast dark interface using varying shades of gray to create hierarchy. It uses the Inter font family with specific weights (Bold for titles, Medium for buttons, Semibold for subheadings). Borders are thin (1px) and translucent, while icons are thin-line Lucide variants. Animations are minimal, focusing on subtle background color shifts on hover.",
    "prompt": "Create a UI with a background color of #191919 and text color of #FFFFFF. Use 'Inter' as the primary font family. Define a card style ('notion-border') with background #202020, 1px solid border of rgba(255, 255, 255, 0.08), and a small border-radius of 2px. Primary accent color is #0075de for active buttons and highlights. Secondary text color is #9B9B9B. Use font-size 20px for headers, 15px for card titles, 13px for descriptions, and 10px for utility badges. Micro-interactions should include a hover state on cards that changes background to rgba(255, 255, 255, 0.03) with a quick transition-color ease-in-out."
  },
  "layout_and_structure": {
    "description": "A mobile-first vertical stack layout featuring a sticky-style header, a scrollable content area with distinct semantic sections (Grids, Callouts, Lists), and consistent 24px (6 units) horizontal padding.",
    "prompts": [
      {
        "part": "Header",
        "prompt": "The header section should have a pt-14, px-6, and pb-6 layout. Include a left-aligned title 'Home' at text-xl font-bold. On the right, place a horizontal flex container with two elements: a status badge (#202020 background, 1px border, text-sm) showing a balance, and a primary CTA button (#0075de background, text-white, px-3 py-1.5, text-sm font-medium) with a plus icon."
      },
      {
        "part": "Utility Grid (Credits & Rates)",
        "prompt": "A section titled 'Credits & Rates' in #9B9B9B uppercase text-xs font-semibold. Below it, a 2-column grid with a 12px gap. Each card is a vertical flexbox with p-5, a 32x32px square icon container with #2e2e2e background, and a 15px font-medium title. The card should have the standard 'notion-border'."
      },
      {
        "part": "Feature Callout Banner",
        "prompt": "A promotional banner using the Notion callout style: #202020 background, notion-border, and a 4px wide left border of #0075de. Layout is a flex row with a 16px gap. Left side contains a 24px icon in blue. Right side contains a 15px font-semibold title and 13px #9B9B9B description. At the bottom, include a horizontal row of tags (#2e2e2e background, 10px bold text) separated by a thin 5% white border line."
      },
      {
        "part": "Horizontal List Item (Referral)",
        "prompt": "A wide card (notion-border) with p-5. Flex row layout containing a 40x40px #2e2e2e icon container on the left, a central text block (15px title, 13px subtext), and a right-aligned chevron icon in #9B9B9B."
      },
      {
        "part": "Resource Grid",
        "prompt": "A 2-column grid for resources. Cards follow the standard notion-border and p-5 padding. Include a notification badge on the icon for the first card: a small #0075de square with 9px bold white text positioned at the top-right of the icon."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Notion-Style Icon Box",
      "description": "A squared icon container used inside cards.",
      "prompt": "A container with width and height of 32px or 40px, background color #2e2e2e, border-radius of 2px (rounded-sm), and centered flex content for icons."
    },
    {
      "component": "Micro-Badge Tags",
      "description": "Small utility tags for displaying brands or categories.",
      "prompt": "Inline-block elements with background #2e2e2e, border-radius 4px, font-size 10px, font-weight 700 (bold), color #9B9B9B, and padding 2px 8px."
    }
  ]
}

{
  "summary": "A clean, document-inspired dark mode UI design that replicates the Notion aesthetic using a deep charcoal theme, sharp rectangular elements, and subtle gray borders for a structured, utilitarian layout.",
  "style": {
    "description": "The style is characterized by high legibility, low-strain dark backgrounds, and a 'blocks' based layout. It pairs the Inter font family with a monochromatic palette, using a specific blue (#0075de) for primary actions. Borders are extremely subtle, and corners use a very small 2px radius for a nearly sharp look.",
    "prompt": "### Visual Theme\n- **Color Palette:** Primary background: `#191919`; Surface/Card background: `#202020`; Icon containers: `#2e2e2e`; Accent color: `#0075de`; Text colors: White (`#FFFFFF`) for primary, Muted Gray (`#9B9B9B`) for secondary/labels.\n- **Typography:** Font Family: 'Inter', sans-serif. Sizes: H1/Title: 20px (Bold); Section Headers: 12px (Semi-bold, Uppercase, 0.05em tracking); Body/Card titles: 15px (Medium); Subtext: 13px (Regular).\n- **Borders & Shadows:** No box-shadows. Borders: 1px solid `rgba(255, 255, 255, 0.08)`. Border-radius: 2px (sharp but not harsh).\n- **Interactive States:** Hover state for cards: `background-color: rgba(255, 255, 255, 0.03)`. Transitions: 200ms ease-in-out color and background transitions.\n- **Icons:** Minimalist white stroke icons (Lucide-style) with a consistent 20px-24px sizing."
  },
  "layout_and_structure": {
    "description": "A mobile-first, single-column scrollable layout with a fixed bottom navigation bar and grouped 'block' sections.",
    "prompts": [
      {
        "part": "Header",
        "prompt": "Fixed-top or top-aligned header with a height of roughly 80px. Left-aligned H1 title ('Home') in 20px bold text. Right-aligned action area containing a balance indicator (gray surface, 1px border) and a primary 'Credits' button in blue (#0075de) with a '+' icon and sharp corners."
      },
      {
        "part": "Grid Action Section",
        "prompt": "Two-column grid with a 12px gap. Each card is a 'Notion-style' block: background `#202020`, 20px padding, 2px border radius. Elements inside: a small 32x32px icon square in `#2e2e2e` and a 15px medium-weight label below it. Full-card clickability with a subtle hover color change."
      },
      {
        "part": "Callout Banner",
        "prompt": "A full-width container mimicking the Notion 'Callout' block. Background `#202020`, 1px border on three sides, and a distinct 4px thick left border in accent blue (#0075de). Layout: icon on the left (24px), content on the right. Includes a horizontal divider (`border-top: 1px solid rgba(255, 255, 255, 0.05)`) and a footer area with small status tags in `#2e2e2e`."
      },
      {
        "part": "Bottom Navigation",
        "prompt": "Fixed footer at the bottom. Background `#191919` with a subtle top border. Five equally spaced navigation items. Active item: White (`#FFFFFF`) with 100% opacity. Inactive items: White with 40% opacity. Each item consists of a 20px icon and a 10px font-size label. Include a small notification dot (6px blue circle) on icons where status updates are present."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Status Notification Badge",
      "description": "Small, sharp-cornered square badge for notifications.",
      "prompt": "A 16x16px square with 2px radius, background `#0075de`, text white, font-size 9px, bold. Centered text. Used as an overlay on icons to indicate unread counts."
    },
    {
      "component": "Notion Action Card",
      "description": "Standard interactive block for navigation.",
      "prompt": "Container background: `#202020`; Padding: 20px; Border: 1px solid `rgba(255, 255, 255, 0.08)`; Layout: Vertical stack (icon then text) for grids or horizontal stack (icon, text-group, chevron) for lists. Icons are always placed in a slightly lighter `#2e2e2e` square background."
    }
  ]
}

{
  "summary": "A highly structured, professional technical architecture diagram using a modular grid. It features side pillars for data sources and consumers with a centralized multi-layer platform engine. The visual language is defined by soft shadows, subtle borders, and a monochromatic blue-tinted secondary palette.",
  "style": {
    "description": "The style is 'Modern Enterprise Professional'. It relies on the Satoshi font family for clarity. The color palette uses #FAFBFC for the page background, #EAF2FA for peripheral zone backgrounds, and #FFFFFF for primary content cards. Accents are primarily #3B82F6 (Blue), #6366F1 (Indigo), and #06B6D4 (Cyan). Borders are consistent at 1px solid #CBD5E0. Typography focuses on #2D3748 for headings and #4A5568 for labels. Layout uses rounded-xl (12px) and rounded-lg (8px) for structural hierarchy.",
    "prompt": "Create a design with a background of #FAFBFC. Typography must use 'Satoshi' or a similar clean sans-serif. Main headings should be #2D3748, bold, font-size: 14px, leading-tight. Secondary text should be #4A5568, font-size: 10px to 14px. Containers must have 1px solid #CBD5E0 borders and 'shadow-sm' (subtle 0 1px 2px 0 rgba(0, 0, 0, 0.05)). Use specific color accents: Blue (#3B82F6), Indigo (#6366F1), and Cyan (#06B6D4). Structural corner radius is 12px for sections and 8px for internal cards. Include a decorative element: a 2px high, 32px wide horizontal rule in bg-blue-500/20 under section titles. Icons should be consistent in size (approx 18px-20px) and use the accent blue #3B82F6."
  },
  "layout_and_structure": {
    "description": "A horizontal flow layout from left-to-right, divided into four logical zones using a 15% / 70% / 15% width distribution. The central 70% zone is further subdivided into operational layers and functional blocks.",
    "prompts": [
      {
        "part": "Peripheral Pillars (Zones 1 & 4)",
        "prompt": "Design two narrow vertical sidebars (15% width each) with a background of #EAF2FA. Each sidebar is an encapsulated container with a border (#CBD5E0) and 12px radius. Inside, place a header with a title and a subtle blue underline. Below the header, arrange a vertical stack of small white cards (bg-white, border #CBD5E0, radius 8px). Each card contains a centered icon and a bold label (10px). Spacing between cards should be 12px (3 units)."
      },
      {
        "part": "Platform Core (Zone 2 - Operational Planes)",
        "prompt": "In the central area, create a vertical stack of three horizontal cards occupying approx 35% of the inner width. Each card should be white, border #CBD5E0, radius 12px, p-5. The content is horizontally aligned: a colored icon background (blue-50, indigo-50, or cyan-50) containing a themed icon, followed by a bold text label (#2D3748, 14px)."
      },
      {
        "part": "Platform Foundation (Zone 3 - Knowledge Base)",
        "prompt": "Next to the operational planes, create a wide container (65% width) containing two equal-width vertical columns. Each column is a white card (radius 12px, p-6). Inside each column, list 4 items vertically. Each item consists of a centered icon (#3B82F6) above a text label (14px, #4A5568). Distribute the items evenly to fill the vertical height."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Accent Icon Box",
      "description": "A small, rounded container for icons within cards.",
      "prompt": "Create a square div (approx 40px) with bg-blue-50 (or relevant tinted background), rounded-lg (8px). Center a Lucide icon inside it with a stroke width of 2px and color matching the background's primary hue (e.g., #3B82F6 for blue-50)."
    },
    {
      "component": "Data Source Card",
      "description": "Miniature cards used for inputs/outputs.",
      "prompt": "A compact white card (bg-white) with 1px solid #CBD5E0 border. Padding is 10px. Layout is a vertical stack: centered icon at top, 10px bold text at bottom. Shadow: shadow-sm."
    }
  ],
  "special_notes": "MUST use 'Satoshi' font for the premium enterprise feel. MUST NOT use vibrant gradients; keep colors flat or very subtly tinted. MUST ensure all internal cards (inner boxes) have a consistent 10px padding for labels. MUST use a 24px (6 units) gap between major layout zones. Stroke-dasharray of 4, 4 should be used for any connecting paths between zones to maintain technical schematic integrity."
}

{
  "summary": "A premium editorial design system for insurtech that prioritizes 'speed' and 'craftsmanship' through bold typography, high-contrast brand colors, and fluid, non-linear micro-interactions.",
  "style": {
    "description": "The design uses 'Instrument Serif' for expressive, large-scale editorial headings (italicized for emphasis) and 'Plus Jakarta Sans' for functional body and UI text. The color system is built on a navy foundation (#202847) with a vibrant emerald primary (#0ACF83) and soft mint accents (#EEFBF4). Containers feature extreme rounding (30px-64px) and subtle depth is achieved through 100px-120px background blurs and glassmorphism headers.",
    "prompt": "Apply an 'Editorial Insurtech' style. Primary Brand Color: #0ACF83 (Coverdash Green); Foundation Color: #202847 (Deep Navy); Background Accent: #EEFBF4 (Soft Mint); Typography: 'Instrument Serif' for H1-H3 (tracking-tight, italicized emphasis) and 'Plus Jakarta Sans' for body and UI elements (weights 400-700). Animations: All entries must use a cubic-bezier(0.16, 1, 0.3, 1) curve with a 900ms duration, featuring a fade-up with a 2-degree starting rotation. Borders/Corners: Use a minimum of 24px and up to 64px (4rem) corner radii for major sections. Shadows: Buttons use shadow-lg shadow-primary/20; high-impact sections use shadow-primaryGlow (0 18px 40px rgba(10,207,131,0.22)). Navigation: Fixed glassmorphism bar (white/60 opacity, 12px backdrop-blur). Background: Use large ambient blur circles (#0ACF83 at 8-10% opacity) for atmospheric depth."
  },
  "layout_and_structure": {
    "description": "Modular, scroll-responsive layout utilizing full-width hero sections, asymmetric bento grids for product showcases, and clear status-oriented UI dashboards.",
    "prompts": [
      {
        "part": "Global Navigation",
        "prompt": "Fixed top navigation. Left: Logo mark in a #0ACF83 container with a default 3-degree rotation (rotates to 12 degrees on hover). Center: Text links in Plus Jakarta Sans (text-sm, font-semibold, #202847 at 80% opacity). Right: Pill-shaped 'Get a Quote' button (#0ACF83, white text, uppercase text-xs, tracking-widest). On scroll, background transitions to white/80 with 12px backdrop-blur."
      },
      {
        "part": "Hero Section",
        "prompt": "Centered layout. Top: Small pill badge (#EEFBF4 background, green dot pulse, 'Instant Coverage' text). Heading: Dual-line H1 using Instrument Serif at 10rem (160px), first line #202847, second line #0ACF83 and italicized. Subtext: Max-width 2xl, Plus Jakarta Sans text-lg, #202847/70. CTAs: Primary #0ACF83 pill button with heavy glow shadow; Secondary ghost button with 2px border-navy/10. Background: Large green ambient blur circles at edges."
      },
      {
        "part": "Integration Bar",
        "prompt": "Grid layout. Left: Carrier heading in Serif H2. Right: 'Partner Network' component—a navy browser window (#202847) containing a white interface mockup with a scrolling marquee of carrier names. Marquee items should transition from grayscale to primary green on hover."
      },
      {
        "part": "Insurance Product Bento",
        "prompt": "Two-column layout. Left: Vertical feature list with 56px rounded-2xl icon containers (mint background) for each product category. Right: 'Quote Simulator'—a dark-themed mockup window showing a 3-step quote flow with abstract skeleton loaders and a 'Coverage Bound' status bar."
      },
      {
        "part": "Who We Insure Grid",
        "prompt": "Asymmetric bento grid using 3-column logic. Cards use 48px (3rem) corner radii. Large card (spans 2 columns): White background, subtle border, featuring a large ghosted store icon (5% opacity). Startup card: Solid #202847 background, white text, #0ACF83 accent checkmarks. E-Commerce cards: Simple white backgrounds with grid lists of partners/platforms."
      },
      {
        "part": "Customer Dashboard Preview",
        "prompt": "Mint background (#EEFBF4) section. Centered Serif H2 heading. Content: Alternating feature rows using two-column grids. One column contains text (Plus Jakarta Sans), the other contains UI snippets (e.g., policy lists, COI generators, or support chat windows) within rounded white containers."
      },
      {
        "part": "Embedded Partner CTA",
        "prompt": "Full-width 64px (4rem) rounded container in solid #0ACF83. Background: Subtle white dot grid pattern (20% opacity, 30px spacing). Heading: Large Serif text (8rem). Buttons: High-contrast white background with green text. Include a trust-bar at the bottom with uppercase, tracking-widest documentation links."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Animated Quote Simulator",
      "description": "A navy-themed floating browser mockup representing the quote experience.",
      "prompt": "Container: #202847 background, 40px radius. Header: 3 dots and a skeleton URL bar. Internal: White container with 3 sections: step-indicator, 2-column skeleton grid for selectors, and a footer bar. Footer: Glassmorphism bar with a green check-circle and 'Coverage Bound' label plus mono-spaced policy tags (e.g., 'GL', 'BOP') in dark capsules."
    },
    {
      "component": "Rotating Brand Mark",
      "description": "Dynamic, interactive logo container.",
      "prompt": "36px square #0ACF83 container with a 3-degree rotation. Contains a white 'C' in bold italic Serif. Micro-interaction: On hover, rotate to 12 degrees and scale by 1.05x using a 300ms transition."
    },
    {
      "component": "Live Coverage Status Badge",
      "description": "Inline status pill with pulse animation.",
      "prompt": "Pill shape, #EEFBF4 background, 1px border (#0ACF83/20). Content: 8px solid #0ACF83 dot with a pulse-ring animation (expanding glow), followed by uppercase Plus Jakarta Sans text at 11px, tracking-widest."
    }
  ],
