            className="bg-[rgba(34,34,34,0.8)] text-white [font-family:Inter,Inter-Regular,system-ui,Arial,sans-serif,system-ui,sans-serif] font-medium w-max h-fit fixed block shrink-0 shadow-[rgba(0,0,0,0.1)_0px_2px_4px_0px,rgba(0,0,0,0.05)_0px_1px_0px_0px,rgba(255,255,255,0.15)_0px_0px_0px_1px] opacity-0 backdrop-blur-[10px] caret-white pointer-events-none select-none px-2 py-1 rounded-br-[8px] rounded-t-[8px] rounded-bl-[8px] left-auto right-10 inset-y-auto"
