                btn.classList.add('text-gray-900');
                btn.classList.remove('text-gray-300');
                btn.querySelector('.indicator').classList.replace('w-1', 'w-6');
                btn.querySelector('.indicator').classList.replace('bg-transparent', 'bg-gray-900');
            });
        });

        render();
    </script>
</body>
