  <script>
    document.addEventListener('DOMContentLoaded', () => {
      const track = document.getElementById('carousel-track');
      const dots = document.querySelectorAll('.dot');
      const nextBtn = document.getElementById('btn-next');
      const backBtn = document.getElementById('btn-back');
      const skipBtn = document.getElementById('btn-skip');
      const stepLabel = document.getElementById('step-label');

      let currentStep = 0;
      const totalSteps = 5;

      function updateCarousel() {
        // Slide track
        track.style.transform = `translateX(-${currentStep * 100}%)`;

        // Update Dots
        dots.forEach((dot, index) => {
          if (index === currentStep) {
            dot.classList.remove('bg-gray-200', 'hover:bg-gray-300');
            dot.classList.add('bg-gray-800');
          } else {
            dot.classList.add('bg-gray-200', 'hover:bg-gray-300');
            dot.classList.remove('bg-gray-800');
          }
        });

        // Update Buttons visibility/text
        if (currentStep === totalSteps - 1) {
          nextBtn.textContent = 'Get Started';
          skipBtn.classList.add('invisible');
        } else {
          nextBtn.textContent = 'Next';
          skipBtn.classList.remove('invisible');
        }

        if (currentStep === 0) {
          backBtn.classList.add('invisible');
        } else {
          backBtn.classList.remove('invisible');
        }

        // Update Label
        stepLabel.textContent = `Wireframe v1.0 • Screen 0${currentStep + 1}/05`;
      }

      // Event Listeners
      nextBtn.addEventListener('click', () => {
        if (currentStep < totalSteps - 1) {
          currentStep++;
          updateCarousel();
        } else {
          // Reset for demo purposes
          currentStep = 0;
          updateCarousel();
        }
      });

      backBtn.addEventListener('click', () => {
        if (currentStep > 0) {
          currentStep--;
          updateCarousel();
        }
      });

      skipBtn.addEventListener('click', () => {
        currentStep = totalSteps - 1;
        updateCarousel();
      });

      dots.forEach((dot, index) => {
        dot.addEventListener('click', () => {
          currentStep = index;
          updateCarousel();
        })
      });
    });
  </script>
</body>
</html>
