    ]
  },
  "special_ui_components": [
    {
      "component": "Bauhaus Composition Box",
      "description": "An intricate geometric grid assembly that houses a profile image.",
      "prompt": "A 12x12 grid container. Top-left 5x4 cells: #D02020. Center 8x8 cells: White background with a 300px aspect-ratio [3/4] blue oval (#1040C0). The oval contains an image with mix-blend-mode: multiply. Bottom-right 4x5 cells: #F0C020. All major grid intersections marked with 4px borders."
    },
    {
      "component": "Interactive Bauhaus Button",
      "description": "A tactile, geometric button with a binary state.",
      "prompt": "Border: 4px solid #121212; Background: #F0C020 (Yellow) or White; Padding: 12px 16px; Shadow: 8px 8px 0px #121212; Font: Outfit Black Uppercase. Active state: transform: translate(2px, 2px); shadow: 6px 6px 0px #121212; transition: all 0.1s ease-in-out."
    }
  ],
  "special_notes": "MUST: Maintain the 4px border weight consistently across all elements. MUST: Use only hard-edged shadows. MUST: Implement the scroll-parallax effect on the container plane to achieve the 'tilted poster' feel. DO NOT: Use any gradients (except for the background grain) or blurred effects. DO NOT: Use soft-rounded corners; strictly sharp or circular."
}

{
  "summary": "A geometric, high-contrast design system based on Bauhaus principles, utilizing a 3D perspective transform that updates dynamically on scroll to create a 'tilted plane' effect for all content.",
