/**
 * Main application component for JupUSD cloning.
 * Features:
 * - Full page layout with fixed star field background
 * - Responsive sections
 * - Dynamic script loading for animations
 */
import React, { useEffect } from 'react';
import Component_1 from './components/Component_1';
import Component_2 from './components/Component_2';
import Component_3 from './components/Component_3';
import Component_4 from './components/Component_4';
import Component_5 from './components/Component_5';
import Component_6 from './components/Component_6';
import Component_7 from './components/Component_7';
import Component_8 from './components/Component_8';
import Component_9 from './components/Component_9';
import Component_10 from './components/Component_10';

function App() {
  useEffect(() => {
    // Add custom Satoshi font to head
    const style = document.createElement('style');
    style.textContent = `
      @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');
      :root {
        --font-satoshi: 'Plus Jakarta Sans', sans-serif;
      }
      body {
        background-color: black;
        color: white;
        font-family: var(--font-satoshi);
        margin: 0;
        overflow-x: hidden;
      }
      .gradient-text {
        background: linear-gradient(90deg, #c7f284 0%, #00bef0 100%);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
      }
    `;
    document.head.appendChild(style);
  }, []);

  return (
    <div className="min-h-screen bg-black text-white selection:bg-primary/30">
      {/* Dynamic Star Field Background */}
      <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
        {[...Array(50)].map((_, i) => (
          <span 
            key={i}
            className="absolute bg-white rounded-full opacity-40 animate-pulse"
            style={{
              width: Math.random() * 3 + 'px',
              height: Math.random() * 3 + 'px',
              left: Math.random() * 100 + '%',
              top: Math.random() * 100 + '%',
              animationDelay: Math.random() * 5 + 's',
              animationDuration: Math.random() * 3 + 2 + 's'
            }}
          />
        ))}
      </div>

      <div className="relative z-10">
        <div className="flex flex-col items-center mb-[120px]">
          <Component_1 />
          <Component_2 />
        </div>

        <div className="w-full max-w-[1440px] mx-auto">
          <Component_3 />
          <Component_4 />
          <Component_5 />
          <Component_6 />
          <Component_7 />
          <Component_8 />
          <Component_9 />
        </div>

        <footer className="bg-black py-16 px-10 border-t border-white/5">
          <Component_10 />
        </footer>
      </div>
    </div>
  );
}

export default App;
