/**
 * Shared FAQ components for JupUSD.
 */
import React, { useState } from 'react';

function GenericFAQ({ question, answer, id }) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div
      className="caret-white"
      data-component-id={id}
    >
      <div
        role="button"
        onClick={() => setIsOpen(!isOpen)}
        className={`bg-black/60 w-full relative overflow-hidden backdrop-blur-md caret-white select-none mx-auto px-8 py-6 rounded-2xl border transition-all ${isOpen ? 'border-primary shadow-[0_0_20px_rgba(0,190,240,0.1)]' : 'border-white/10 hover:border-white/20'}`}
      >
        <div className="relative z-10 caret-white select-none">
          <div className="w-full flex justify-between items-center gap-4">
            <span className="leading-[28px] font-bold text-[18px] md:text-[20px] text-left block text-white">
              {question}
            </span>
            <div className={`bg-white/5 flex items-center p-2 rounded-lg transition-transform ${isOpen ? 'rotate-180' : ''}`}>
              <svg className="w-4 h-4 text-primary" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
              </svg>
            </div>
          </div>
          {isOpen && (
            <div className="mt-6 pt-6 border-t border-white/5 animate-in fade-in slide-in-from-top-2 duration-300">
               <p className="text-[#cad5e2] text-sm leading-relaxed">
                  {answer}
               </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export function Component_8_2() {
  return <GenericFAQ id="Component_8_2" question="How is JupUSD backed?" answer="JupUSD is 100% backed by USDtb, a stablecoin issued by Anchorage Digital Bank and reserved with institutional-grade assets including BlackRock's BUIDL Fund. This ensures high stability and security for all holders." />;
}
export function Component_8_3() {
  return <GenericFAQ id="Component_8_3" question="Where can I swap JupUSD?" answer="You can swap JupUSD on Jupiter Exchange (jup.ag). It is integrated with deep liquidity pools on Meteora and other major Solana DEXs through Jupiter's world-class routing." />;
}
export function Component_8_4() {
  return <GenericFAQ id="Component_8_4" question="Is JupUSD audited?" answer="Yes, JupUSD's smart contracts and infrastructure are rigorously audited by leading security firms including Offside Labs, Guardian, and Pashov Audit Group. All audit reports are publicly accessible." />;
}
export function Component_8_5() {
  return <GenericFAQ id="Component_8_5" question="What are the benefits of using JupUSD?" answer="As a Jupiter-aligned stablecoin, JupUSD offers deep integration with Jupiter Perps, Lend, and Spot. Holders benefit from institutional-grade backing while supporting the growth of the Solana DeFi ecosystem." />;
}
