  ]
}

{
  "summary": "A sophisticated, structural design system inspired by technical blueprints and high-end UI wireframes. It utilizes a large-scale mosaic background of interlocking rectangular panels, razor-thin hairlines, and a prestige-green primary color. The aesthetic is flat, 2D, and emphasizes high negative space and structural precision.",
  "style": {
    "description": "The style is 'Technical Minimalist'. It pairs a sans-serif header (Space Grotesk) with a monospaced functional font (JetBrains Mono). The color scheme revolves around 'Paper' (#F7F7F5), 'Forest' (#1A3C2B), and 'Grid' (#3A3A38). It avoids all depth effects (shadows, gradients) in favor of 1px border-lines and flat color blocks. Micro-interactions are snappy with linear or standard ease-out curves.",
    "prompt": "Create a design system using a 'Paper' background (#F7F7F5) and 'Forest Green' (#1A3C2B) as the primary brand color. Typography: Use 'Space Grotesk' for bold, tight-tracking headers (font-size: 64px-96px, line-height: 0.9); 'General Sans' for body text; and 'JetBrains Mono' for all labels, tags, and small technical metadata (font-size: 10px-12px, tracking: 0.1em). Borders: Use 1px hairlines in #3A3A38 at 20% opacity for all dividers. Palette: Primary Forest (#1A3C2B), Coral (#FF8C69), Mint (#9EFFBF), and Gold (#F4D35E). Styling: No box shadows. All components must have 0px or 2px (sm) border-radius. Images should use 'mix-blend-luminosity' with a 90% opacity and shift to full color on hover."
  },
  "layout_and_structure": {
    "description": "A vertical-scroll structure characterized by section-wide dividers and a background mosaic grid. Sections are divided by explicit 1px horizontal lines. Components often sit in a 'Bento Grid' format where blocks are separated by 1px gaps.",
    "prompts": [
      {
        "part": "Mosaic Background",
        "prompt": "Implement a full-page background pattern using an SVG mosaic of interlocking rectangular panels. Panels should have varying sizes (large squares, horizontal strips, vertical blocks) divided by 0.5px hairlines (#3A3A38 at 0.3 opacity). Fill all panels with #F7F7F5. The pattern should repeat seamlessly."
      },
      {
        "part": "Technical Navigation",
        "prompt": "Fixed top header with a 1px border-bottom (#3A3A38/20). Left side: square logo box (32x32px) in #1A3C2B with a white icon. Center: Nav links in JetBrains Mono, 10px, uppercase, prefixed with numerical indices (e.g., '01. Pricing'). Right side: Ghost button (1px border) and a solid Forest green button."
      },
      {
        "part": "Hero Section",
        "prompt": "Large typography layout. Header text 'Space Grotesk' 8xl, tracking-tight, forest green. Subtext in JetBrains Mono, 14px, all-caps, with a vertical 1px line on the left. Include an abstract wireframe graphic on the right: a square container with a dashed circular orbit and a luminosity-blended image."
      },
      {
        "part": "Bento Feature Grid",
        "prompt": "A 2x2 grid layout with a 1px 'Grid' color gap separating the cells. Each cell has a 'Paper' (#F7F7F5) background, 32px padding, and a monospaced header label with a colored left-border accent (Coral, Mint, Gold). Include internal 'mockup' boxes that simulate code snippets or UI errors using monospaced text and flat color chips."
      },
      {
        "part": "Technical Form CTA",
        "prompt": "A centered 640px wide form box. Background: #F7F7F5, Border: 1px hairline. Add four L-shaped 'corner markers' (10px x 10px) in #1A3C2B at each corner of the container. Form fields use solid white backgrounds with 1px borders and monospaced labels positioned directly above inputs."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Status Badge",
      "description": "A minimalist indicator for system status.",
      "prompt": "Create an inline-flex container with 1px border (#1A3C2B/20). Inside, place a 8px x 8px square dot of solid #1A3C2B followed by JetBrains Mono text at 10px, uppercase, tracking-widest. Padding: 4px 12px."
    },
    {
      "component": "Network Topology Graph",
      "description": "An abstract SVG visualization of a design system network.",
      "prompt": "A circular container (max-width: 450px) with 1px border. Central 16px solid forest green node. Three orbiting nodes on dashed paths (140px radius). Connect nodes to center using 1px solid lines at 0.2 opacity. Animate orbiting nodes with a linear 20s infinite rotation."
    },
    {
      "component": "Monospaced Testimonial Card",
      "description": "Flat testimonial card with technical metadata.",
      "prompt": "1px bordered square card. Top: Quote icon and star ratings (5 icons, 10px each). Body: Monospaced text at 12px, line-height 1.6. Bottom: 1px top border with user avatar (square, no radius) and name/title in JetBrains Mono."
    }
  ]
}

{
  "summary": "Superdesign is a sophisticated, vibe-centric design system that blends deep slate atmospheric backgrounds with a clean, grid-based feature layout. It utilizes a mix of 'Inter' (sans) for utility, 'Lora' (serif) for emotional headlines, and 'Space Grotesk' for a technical edge. The visual identity relies on glass panels (blur 12px), vibrant indigo accents (#6366f1), and animated glow gradients to create a futuristic, premium feel.",
  "style": {
    "description": "The style is 'Modern Atmospheric'. It pairs dark, deep backgrounds (#0f172a) in the hero and testimonials with clean, off-white surfaces (#f8f9fa) for detailed features. Typography is a critical pillar, using a serif font (Lora) for large, expressive headlines and a high-legibility sans (Inter) for body text. Animations are subtle but intentional: typing cursors, 180-degree logo rotations on hover, and 500ms smooth transitions for sticky navigation states.",
    "prompt": "### Visual Language\n- **Base Palette**: Primary Dark (#0f172a), Brand Indigo (#6366f1), Surface White (#f8f9fa), Border White (rgba(255,255,255,0.1)).\n- **Typography**: \n  - Headlines: Serif (Lora), 400-700 weight, tracking-tight, leading 1.1.\n  - UI/Body: Sans (Inter), 400-600 weight, leading-relaxed.\n  - Accents/Branding: Display (Space Grotesk), tracking-tight.\n- **Glassmorphism**: \n  - Soft: `background: rgba(255, 255, 255, 0.05); backdrop-filter: blur(12px); border: 1px solid rgba(255, 255, 255, 0.1);`.\n  - Strong: `background: rgba(30, 41, 59, 0.7); backdrop-filter: blur(16px); border: 1px solid rgba(255, 255, 255, 0.1); shadow: 0 4px 30px rgba(0, 0, 0, 0.1);`.\n- **Effects**: \n  - Outer Glow: `radial-gradient(from-indigo-500 via-purple-500 to-pink-500), blur(20px), opacity(0.3)`. \n  - Grid Overlays: Subtle 1px grid pattern with linear-gradient masks."
  },
  "layout_and_structure": {
    "description": "A tiered layout starting with a 110vh atmospheric hero section, transitioning into a multi-column feature section with sticky side-navigation, followed by a glassmorphic masonry testimonial grid and a clean accordion-based FAQ.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Sticky or absolute top navigation. Logo on left (icon + bold lowercase text). Center: a capsule-shaped pill `bg-white/10 backdrop-blur-md` containing links. Right: Primary CTA button with `shadow-[0_0_20px_rgba(255,255,255,0.2)]`."
      },
      {
        "part": "Hero Section",
        "prompt": "Full viewport (110vh). Background: Image overlayed with a slate-900 to transparent gradient. Center-aligned content. Top: Small indigo badge with a 'New' tag. Middle: Serif headline (text-7xl). Bottom: Large white input area (rounded-2xl) with a multi-colored outer glow shadow. Ensure a typing cursor animation on subheading text."
      },
      {
        "part": "Integration Bar",
        "prompt": "Floating glass panel (width: max-w-4xl) at the bottom of the hero. Two-part horizontal split. Left: 'Frameworks' label + logos. Right: 'Integrations' label + marquee/scrollable list of monochrome icons with hover color transitions."
      },
      {
        "part": "Feature Scroll-Spy",
        "prompt": "Light mode background (#f8f9fa). Layout: 25% sticky left sidebar for navigation, 75% main content. Sidebar features vertical links with a dot indicator that activates on scroll. Feature cards are alternating 2-column grids (Text vs Visual). Visuals include code snippets in dark blocks or grayscale blueprints with SVG overlay lines."
      },
      {
        "part": "Testimonials",
        "prompt": "Switch back to Slate-900 background. Use a masonry grid layout. Cards must use 'Glass Strong' style. Profiles include avatar, name, and social handle. Quotes should use 14px text-slate-200 with high line-height."
      },
      {
        "part": "FAQ",
        "prompt": "Centered 4xl container on white background. Items use light gray (#f3f4f6) rounded blocks. Interaction: Smooth height transition from 0 to max-content on click, with chevron rotation."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Vibe Input Box",
      "description": "A high-fidelity text input that feels like a primary command center.",
      "prompt": "White container, 16px padding, rounded-2xl. Underneath, a hidden `div` with absolute positioning and `-inset-1` spacing applies a multi-color gradient (indigo to pink) with a `blur-lg` effect that intensifies on hover. Internal layout includes a borderless textarea (text-xl) and a bottom utility bar with attachment and 'send' (arrow-up) buttons."
    },
    {
      "component": "Sticky Feature Nav",
      "description": "Vertical navigation that tracks user progress through content sections.",
      "prompt": "Left-aligned list. Items transition from text-slate-400 (medium) to text-slate-900 (bold) based on scroll intersection. A 6px rounded circle (bg-black) appears to the left of the active item. Use a 500ms ease-in-out transition for the opacity and color shift."
    }
  ]
}

{
  "summary": "A bold, tactile mobile dashboard featuring 70s-style punk aesthetics, heavy editorial borders, hard block shadows, and vibrant primary accents. The design uses a fixed navigation structure with an interactive graffiti-style map and immersive cards that transition from grayscale to color on interaction.",
  "style": {
    "description": "The style is 'Retro Brutalist'—combining 70s color pops with raw, heavy-duty UI elements. It uses a base of Beige (#F5F1E3) and Charcoal (#2C2C2C). Typography pairs the ultra-bold, high-character Montserrat for headers with the legible Open Sans for body text. Animations are snappy and 'pop-out', utilizing cubic-bezier curves for bouncy, tactile interactions.",
    "prompt": "Apply a 70s Retro Punk aesthetic. Color Palette: Retro Red (#BC2C2C) for highlights/FAB, Retro Blue (#5DA4C9) for accent buttons, Sun Yellow (#FCD758) for tags/tooltips, Beige (#F5F1E3) for main backgrounds, and Charcoal (#2C2C2C) for all borders and text. Typography: Headers use Montserrat (900 weight, uppercase, letter-spacing: -0.05em); Body uses Open Sans (400-600 weight). UI Elements: All containers must have a minimum 6px solid Charcoal border. Shadows must be hard block-style: `box-shadow: 12px 12px 0px 0px #2C2C2C`. Micro-interactions: Cards should rotate (-1deg) and shift position slightly on hover/active. Images: Default state is 100% grayscale, transitioning to full color on interaction."
  },
  "layout_and_structure": {
    "description": "A vertical-scrolling mobile layout composed of a sticky header, a condensed map overview, and a series of high-impact content cards.",
    "prompts": [
      {
        "part": "Sticky Header",
        "prompt": "Create a 64px height header. Background: #BC2C2C. Bottom border: 6px solid #2C2C2C. Left side: Logo in Montserrat Bold, white text, 24px size. Right side: Two icon buttons (calendar, grid) in white. The header must remain fixed at the top of the viewport."
      },
      {
        "part": "Graffiti Map Section",
        "prompt": "Occupies 20% of the viewport height. Background: #5DA4C9 with a subtle noise texture. Encased in an 8px #2C2C2C border. Content: An abstract, hand-drawn style world map using irregular SVG shapes filled with vibrant, mismatched colors (Red, Orange, Yellow, Purple). Feature interactive 'hotspots' as 16px circles with a 2px Charcoal border and a pulsing scale animation. Include small labels (8px font, bold) on white rectangular backgrounds with 2px hard shadows."
      },
      {
        "part": "Immersive Feed Area",
        "prompt": "Occupies the remaining 80% of the height. Include a vertical progress indicator on the far right: 128px tall, 8px wide, rounded, white background with a 2px Charcoal border and a red filling indicating scroll depth. Cards should have a 16px bottom margin and 16px horizontal padding from the screen edge."
      },
      {
        "part": "Content Card",
        "prompt": "Background: #FFFFFF. Border: 6px solid #2C2C2C. Shadow: 12px 12px 0px 0px #2C2C2C. Elements: 1) Full-width image (224px height) with a 4px bottom border, default grayscale. 2) Floating tag in top-left: #FCD758 background, black text, 2px shadow. 3) Content: 32px Montserrat header, 14px Open Sans body. 4) Action row: A 3-button layout featuring a heart icon button (white), a wide 'AI讲解' button (#5DA4C9 background, white text, bold), and a share icon button (white). All buttons must have 4px solid borders and 4px block shadows."
      },
      {
        "part": "Bottom Navigation Bar",
        "prompt": "Height: 80px. Background: #2C2C2C. Top border: 4px solid #2C2C2C. Icons: Yellow (#FCD758) for active, White with 60% opacity for inactive. Centered FAB: A 64px diameter circle in #BC2C2C with a 4px Charcoal border and a 4px block shadow, positioned to overlap the top of the nav bar by 50%."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Tactile Action Button",
      "description": "High-contrast primary color button with physical-press feedback.",
      "prompt": "Design a button with #5DA4C9 background and #2C2C2C 4px border. Shadow is `4px 4px 0px 0px #2C2C2C`. On active state, the button should `translate(2px, 2px)` and the shadow should reduce to `0px 0px`, simulating a physical press. Font: Montserrat 16px, white."
    },
    {
      "component": "Pulsing Map Hotspot",
      "description": "Hand-drawn style interactive point on the map.",
      "prompt": "A circular element with `animation: pulse-dot 2s infinite`. At 0% scale is 1.0, at 50% scale is 1.5 with 0.6 opacity, returning to 1.0 at 100%. Fill color varies (Red/Yellow/White) with a 2px solid #2C2C2C stroke."
    }
  ]
}

{
  "summary": "A dark-mode editorial system that treats software as a physical tool, featuring massive serif headlines, technical metadata annotations, a gritty grain overlay, and a striking '#DFFF00' acid accent.",
  "style": {
    "description": "The style is 'Brutalist Editorial.' It utilizes a strict color palette: Void (#000000), Paper (#FFFFFF), and Acid (#DFFF00). Typography pairings focus on high-contrast extremes: a bold, variable serif (Fraunces) with tight tracking for headlines, and a clean sans (Inter) with ultra-wide tracking (0.3em) for technical labels. Visual effects include a persistent 5% opacity noise/grain overlay, a grid background (40px cells), and scanline animations to mimic high-performance interfaces.",
    "prompt": "Create a design with a background of #000000 and a subtle grid pattern (1px stroke at 5% opacity, 40px grid). Apply a fixed noise overlay at 5% opacity for a film-grain texture. Typography: Use 'Fraunces' (weights 100-900) for headlines with 'tracking-tighter' (-0.08em); use 'Inter' for UI elements and metadata with 'tracking-widest' (0.3em) and uppercase. Accent color: #DFFF00 (Acid Lime). Key visual elements: thin 1px borders, text-stroke effects (transparent fill with #FFFFFF 40% opacity stroke), and mix-blend-mode: exclusion for large text. Animation: Use 'reveal-up' transitions (cubic-bezier(0.16, 1, 0.3, 1)) and a vertical scanline animation across the hero section."
  },
  "layout_and_structure": {
    "description": "A vertical-scrolling editorial layout featuring massive typographic hero blocks, sticky utility bars, and a high-contrast inverted section for core values.",
    "prompts": [
      {
        "part": "Navigation & Metadata",
        "prompt": "Fixed top navigation with pointer-events-none container. Left side: pulsing #DFFF00 dot next to 'SYSTEM ONLINE' label (10px, 0.3em tracking). Right side: 'Manifesto' link with underlined decoration #DFFF00 at 30% opacity. Include building version metadata in #DFFF00 sans-serif."
      },
      {
        "part": "Hero Section",
        "prompt": "Large-scale typographic stack using Fraunces. Headline 1: 'Construct' (12vw, uppercase). Headline 2: 'The Future' (12vw, italic, #DFFF00) preceded by a horizontal 1px line that expands on load. Headline 3: A large numerical stroke text '001' next to 'Yourself'. Bottom left: technical subtitle with 1px border-left and #DFFF00 accent text. Bottom right: 'Scroll to Breach' indicator with a bouncing chevron."
      },
      {
        "part": "Sticky Status Bar",
        "prompt": "A 70px tall sticky bar with #000000 background at 80% blur. Divide into sections with 1px white/10 vertical lines. Left: Release info. Middle: Access protocol with pulse icon. Right: Latency metadata and a #DFFF00 CTA button. The bar should have a 2px #DFFF00 bottom border that animates its width on entrance."
      },
      {
        "part": "Editorial Manifesto",
        "prompt": "Two-column grid (5:7 ratio). Left: Sticky title 'Death to Standardized Thinking' with mono-font system status codes. Right: Large serif body text (4xl) where keywords are highlighted in #DFFF00. Include a blockquote with a 1px border-left in #DFFF00 and large quote icons."
      },
      {
        "part": "System Specs Grid",
        "prompt": "Three-column grid with 1px #FFFFFF/10 borders separating cells. Each cell features: a technical module ID (e.g., MOD.01) in #DFFF00, a serif title that turns #DFFF00 on hover, and a description with 60% opacity. Micro-interaction: background shifts to 2% white on hover."
      },
      {
        "part": "Inverted Creed Section",
        "prompt": "Full-width section with #DFFF00 background and #000000 text. Large-scale vertical list of 'Commandments' (72px serif, uppercase). Numbers should be small-caps sans. Hover effect: text shifts horizontally +1rem."
      },
      {
        "part": "Footer & Call to Action",
        "prompt": "Inverted hero style. Headline: 'Seize the Moment' in stroke-text serif. Background contains two massive concentric 1px circles. CTA: 'Request Access' in 6xl italic serif that scales up on hover, accompanied by a large arrow-right-circle icon."
      }
    ]
  },
