    {
      "component": "Analytics Donut Chart",
      "description": "Minimalist donut chart with centered summary",
      "prompt": "A circular donut chart with a stroke width of 12px. Background track: #F1F3F5. Active segment: #3B82F6. Center text: Large bold percentage (e.g., 72%) with a sub-label (SYSTEM) in 10px uppercase gray."
    },
    {
      "component": "Segmented Control",
      "description": "Time range selection toggle",
      "prompt": "A container with 1px border #D1D5DB, padding 2px. Buttons inside have no border. The 'active' button has a light gray background #F1F3F5 and a subtle shadow. Non-active buttons have gray text #6B7280 and hover-transition to #111827."
    }
  ],
  "special_notes": "Must maintain consistent spacing (24px gutter between cards). Must use Lucide-style line icons. Must ensure charts have a 'dashed line' background grid at regular Y-intervals. Do not use overly rounded 'pill' corners for cards—keep them at 8px for a professional feel."
}

{
  "summary": "A high-end, minimalist waitlist and landing page design system characterized by sophisticated muted colors, slow-motion reveal animations, and meticulous attention to spacing and typographic hierarchy.",
  "style": {
    "description": "The style is 'Quiet Premium'. It uses an Apple-system font stack (SF Pro Display) for a native feel. Colors are anchored in #FAFAFA (background) and #1D1D1F (text), with #4F6BA6 as a muted blue-gray accent. Animation is central: a 1.5s cubic-bezier reveal creates a sense of weight and inevitability. Visual depth is achieved through layered box-shadows rather than borders.",
    "prompt": "Apply a 'Quiet Premium' aesthetic. **Color Palette**: Background: #FAFAFA; Primary Text: #1D1D1F; Secondary Text: #86868B; Accent: #4F6BA6; Muted Accent: #E1E8F5; Dividers: #D2D2D7 at 40% opacity. **Typography**: Use -apple-system stack. Hero headers: font-size 80-128px, font-weight 600, tracking-tight, line-height 1.1. Body context: font-size 24-30px, font-weight 500, line-height 1.6. **Animations**: All section entries must use `transition: all 1.5s cubic-bezier(0.16, 1, 0.3, 1)` with a 30px Y-axis translate and 0.98 scale-up. **Shadows**: Use layered shadows for UI cards: `0 2px 8px rgba(0,0,0,0.04), 0 24px 48px -8px rgba(0,0,0,0.06), 0 48px 80px -12px rgba(0,0,0,0.04)`. **Borders**: Use 1px width with gradient effects for interactive elements."
  },
  "layout_and_structure": {
    "description": "A vertical, centered flow that guides the user through an emotional narrative before the final call to action. It uses full-screen heights for the hero and generous whitespace between sections.",
    "prompts": [
      {
        "part": "Hero Section",
        "prompt": "Create a `min-h-[100vh]` section. Center-align a massive typographic statement. Use font-size 96px (responsive to 48px on mobile). Ensure the leading is exactly 1.1. No other elements should be in this section to maintain impact."
      },
      {
        "part": "Section Dividers",
        "prompt": "Separate major sections with a horizontal line. The line must be a 1px height div with a background gradient: `linear-gradient(to right, transparent, rgba(210, 210, 215, 0.4), transparent)`. Limit width to max-w-2xl."
      },
      {
        "part": "Context & Features",
        "prompt": "Use a max-w-2xl container. Text should be medium-large (text-2xl to 3xl) in #86868B (secondary gray). For feature callouts, use bold #1D1D1F headers (text-5xl) with massive vertical spacing (gap-48) to create a rhythmic scrolling experience."
      },
      {
        "part": "Visual Preview Card",
        "prompt": "A 16:10 aspect ratio card with 24px rounded corners. Background #FFFFFF. Apply the layered shadow spec. Include a header bar with three dots (circles) representing window controls. Fill the interior with abstract skeletal UI elements using #F5F5F7 background blocks."
      },
      {
        "part": "Workflow/Process",
        "prompt": "A horizontal sequence of text labels and icons. Use Lucide icons (arrow-right). Labels in #1D1D1F font-medium. On mobile, stack vertically and switch icons to arrow-down."
      },
      {
        "part": "Waitlist Form",
        "prompt": "Center-aligned form with a max-width of 448px. Input and button should both be `rounded-full` and `h-16`. The input should have a 1px border gradient wrapper that turns blue-gray (#4F6BA6) on focus."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Gradient-Border Input",
      "description": "An input field that appears to have a glowing gradient border on interaction.",
      "prompt": "Wrap the input in a div with 1px padding. Apply `bg-gradient-to-br from-[#E5E5EA] to-[#E5E5EA]`. On `:hover` or `:focus-within`, change gradient to `from-[#4F6BA6] to-[#7C95C8]`. The internal input must be `rounded-full` and white. Add a 300ms transition."
    },
    {
      "component": "Shimmer Action Button",
      "description": "A CTA button with a sophisticated moving gradient.",
      "prompt": "Apply `background: linear-gradient(135deg, #4F6BA6 0%, #5D7BB8 100%)`. Set `background-size: 200% 100%`. On hover, shift `background-position: 100% 0` and apply a soft blue shadow: `0 10px 30px -10px rgba(79, 107, 166, 0.4)`. Use a 0.6s ease transition."
    }
  ],
  "special_notes": "MUST: Maintain the 1.5s animation duration for all reveals; faster durations will break the premium feel. MUST: Use only the specified blue-gray #4F6BA6; do not use standard bright 'Apple Blue' (#0071E3). DO NOT: Use sharp borders; use gradient opacities for dividers. DO NOT: Over-saturate the success state; keep it quiet with a check icon and soft fade."
}

{
  "summary": "Superdesign is a high-energy, unconventional design system that blends neobrutalist hard-shadow aesthetics with modern glassmorphism. It utilizes a striking contrast between deep purple and vibrant neon accents, anchored by dramatic geometric display typography. The layout is structured around interactive 'Identity Calibration' modules and 'Card Stacking' mechanics, perfect for apps that prioritize personality and creative engagement.",
  "style": {
    "description": "The style is characterized by its 'Hard-Shadow' neobrutalism and maximalist color palette. Typography pairings use Clash Display for bold, experimental headlines and Satoshi for clean, readable body text. Visual depth is achieved through animated background blobs, a constant 7% opacity noise grain, and 4px-8px solid-color offset shadows rather than blurs.",
    "prompt": "### Visual Language\n- **Color Palette**: Primary Purple (#2D1B4E), Accent Orange (#FF7D2E), Accent Cyan (#00D4FF), Accent Gold (#FFD166), Background Offwhite (#F9F7F4).\n- **Typography**: Display headlines in 'Clash Display' (Bold/Black weight, tracking-tighter). Body text in 'Satoshi' (Regular/Medium/Bold). Mono labels for technical metadata.\n- **Shadows**: Use 'Hard Shadows' instead of blurs. Default: 4px 4px 0px 0px #2D1B4E. Large: 8px 8px 0px 0px #2D1B4E.\n- **Effects**: Apply a fixed noise texture overlay (SVG fractalNoise at 0.07 opacity). Use glassmorphism (rgba(255,255,255,0.7) + 12px blur) for side panels.\n- **Animations**: Entrance animations using cubic-bezier(0.16, 1, 0.3, 1). Floating elements use a 6s ease-in-out loop. Background blobs use 10s 'metaball' translation/scaling."
  },
  "layout_and_structure": {
    "description": "A dual-pane layout featuring a centered, wide content area for onboarding/input and a fixed 'Live Echo' preview sidebar for real-time visualization.",
    "prompts": [
      {
        "part": "Navigation Header",
        "prompt": "Minimalist top bar with a 40x40px square logo icon (#2D1B4E) with a hard shadow. On the right, include status badges using pill-shaped white containers with thin 1px borders (#2D1B4E/10) and tracking-widest uppercase text."
      },
      {
        "part": "Hero Entrance Section",
        "prompt": "Giant display typography (text-8xl to 9xl) with a line-height of 0.9. One keyword should feature a horizontal gradient (Orange to Gold to Cyan). Include a primary CTA button with a hard shadow that disappears on hover/active states as the button translates 1px."
      },
      {
        "part": "Identity Selection Grid",
        "prompt": "A grid of interactive cards. Each card features a 2px border (#2D1B4E/10) and 24px rounded corners. Upon selection (checked state), the card flips to a solid #2D1B4E background with white text and applies a hard shadow. Icons are placed in high-contrast circular backgrounds."
      },
      {
        "part": "Interactive Card Stack",
        "prompt": "A cluster of 'Goal' cards (aspect ratio 3:4) positioned absolutely with varying rotation values (-4deg to 5deg). Cards use vibrant background fills (Cyan, Gold, Purple). On hover, cards must rotate to 0deg, scale by 1.05, and elevate their z-index."
      },
      {
        "part": "DNA Toggle Grid",
        "prompt": "Two-column grid of workspace settings. Each row features a bold display label and a segmented control toggle. Active toggle states use high-contrast fills (Orange or Purple) with white text, while inactive states are light gray."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Orbital Intelligence Dial",
      "description": "A complex circular interaction module representing AI involvement levels.",
      "prompt": "Create a central 128px white circle 'knob' with a 2px purple border and hard shadow. Surround it with two concentric dashed border rings rotating in opposite directions. Place 4 satellite buttons (pill-shaped) at 0, 90, 180, and 270 degrees. Buttons should highlight with brand colors (Orange, Cyan, Gold) and scale on hover."
    },
    {
      "component": "Live Echo Panel",
      "description": "A sticky glassmorphism sidebar that acts as a terminal and preview area.",
      "prompt": "A 400px wide sidebar with backdrop-filter: blur(12px). Top section contains a 20px dot grid background with floating 3D shapes. Bottom section is a terminal-style console with #2D1B4E background, white monospace text, and 'System Status' logs featuring color-coded keys (Cyan for status, Orange for identity)."
    }
  ]
}

{
  "summary": "An editorial onboarding flow with a warm minimalist aesthetic, featuring huge typography, a noise-textured background with organic floating blobs, and high-precision interactive UI components.",
  "style": {
    "description": "The style is 'Warm Minimalist Editorial.' It uses Clash Display (Variable) for high-impact headings and Satoshi for legible, wide-spaced body text. The color palette is centered on neutrals: Cream (#F8F6F3), Deep Taupe (#6B5D56), and Charcoal (#2A2624), with Muted Rose (#D4A5A5) as a soft accent. Key stylistic traits include a 5% opacity noise overlay, ambient blurred background circles that drift slowly, and a 1.2s cubic-bezier entrance animation for content elements.",
    "prompt": "Apply a design system called 'Superdesign' with the following specs: \n- **Color Palette**: Background: #F8F6F3 (Cream); Primary Text: #2A2624 (Charcoal); Secondary Text: #6B5D56 (Deep Taupe); Accent: #D4A5A5 (Muted Rose); Secondary Accent: #E8DCC8 (Warm Beige).\n- **Typography**: Headings use 'Clash Display', weight 500-700, tracking -0.02em. Hero text size: 96px to 128px (leading 0.9). Body text uses 'Satoshi', weight 400-500, font-size 18px. Labels/Captions: Satoshi, uppercase, tracking 0.15em.\n- **Visual Texture**: Apply a global background noise texture using an SVG filter (fractalNoise, baseFrequency 0.65, 0.05 opacity). \n- **Background Layers**: Include large blurred circles (#E8DCC8 at top-left, #D4A5A5 at bottom-right) with a 20s 'drift' animation (translate 30px, rotate 5deg).\n- **Interactions**: Buttons use #2A2624 background, rounded-full, with 10px padding and a 300ms transition. Hover states for cards should include a subtle -1deg to 2deg rotation change and a shadow: 0 20px 40px -10px rgba(107, 93, 86, 0.15)."
  },
  "layout_and_structure": {
    "description": "The layout follows a centered, single-column scroll-based journey with a max-width of 768px (3xl). Sections are separated by massive vertical gaps (128px to 192px) to ensure focus on individual steps. A persistent floating panel on the right side provides real-time feedback.",
    "prompts": [
      {
        "part": "Header/Navigation",
        "prompt": "A fixed top navigation, 100% width, px-8 py-6. Left: Logo 'Superdesign.' in Clash Display Bold 20px. Right: 'New Workspace Setup' label in Satoshi 12px, uppercase, tracking-widest, opacity 60%. Use mix-blend-darken for background interaction."
      },
      {
        "part": "Floating Echo Panel",
        "prompt": "Fixed bottom-right aside panel (width 288px). Content: white/80 background with backdrop-blur-xl, border white/50, rounded-2xl, shadow-2xl. Inside: A manifesto preview with an abstract visual DNA (spinning concentric circles), status indicators (green pulsing dot), and small progress bars in Deep Taupe/30."
      },
      {
        "part": "Hero Section",
        "prompt": "Min-height 70vh, flex-column, center-aligned. Heading: 'Design at the' followed by an italicized line 'speed of thought.' (Clash Display, 96px+). Subtext: Max-width 448px, Satoshi 20px, opacity 70%. CTA: Rounded-full charcoal button with a lucide:arrow-down icon that translates vertically on hover."
      },
      {
        "part": "Archetype Grid",
        "prompt": "A 2-column grid (1-column on mobile) of selectable cards. Each card: p-8, white/60 background, backdrop-blur-sm, rounded-2xl. On select (checkbox peer-checked): border-deep-taupe and bg-white. Features unique icon containers (40x40 rounded-full) in varying soft pastel colors."
      },
      {
        "part": "Success Masonry",
        "prompt": "A relative container (height 500px) with three overlapping cards. Card 1: Top-left, -1deg rotation. Card 2: Top-right, 120px offset, 2deg rotation. Card 3 (Featured): Center-bottom, charcoal background, cream text, -1deg rotation. All cards transition to 0deg rotation and scale 1.01 on hover."
      },
      {
        "part": "Orbital Control Dial",
        "prompt": "A relationship dial UI. Layout: A central horizontal line with a large semicircular dashed arc above it. A series of vertical tick marks (px-1) connected to the base. A central active node (16px circle) in charcoal. Labels below in Satoshi 12px, tracking-widest, with the active state underlined and bolded."
      },
      {
        "part": "Completion Moment",
        "prompt": "Centered final CTA section. Visual: A 96px white circle with a Lucide:Sparkles icon, floating over a blurred gradient blob (#E8DCC8 to #D4A5A5). Heading: 'Your studio is ready.' 64px Clash Display. Secondary button has deep-taupe/20 border and transparent background."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Interactive Archetype Card",
      "description": "A sophisticated checkbox replacement card that uses peer-state styling.",
      "prompt": "Create a card component using a hidden checkbox input. The wrapper div should be styled with transition-all duration-300. Inside, include a top-row flex container for a colored icon badge (10x10 units) and a custom checkmark indicator (20x20 circle, border-deep-taupe/30). When the hidden input is checked, the outer container should gain a solid border-deep-taupe and the internal checkmark circle should fill with charcoal and show a white Lucide:Check icon."
    },
    {
      "component": "Noise Overlay",
      "description": "A global texture that gives the design a tactile, paper-like feel.",
      "prompt": "Inject an absolute inset-0 div with pointer-events-none and z-index 50. Apply a background-image via data-uri SVG containing a turbulence filter. Set opacity to 0.05 and mix-blend-multiply to ensure it adds grain to all underlying colors without washing them out."
    }
  ]
}

{
  "summary": "A clean, technical configuration wizard with a single-column layout, featuring real-time feedback through an inline state preview panel. It uses a monochrome palette (Zinc/Gray) with emerald accents for status indicators.",
  "style": {
    "description": "The style is built on a 'Technical Minimalist' theme. It pairs Inter for legibility with JetBrains Mono for metadata and system updates. The color palette is strictly monochrome (Zinc 50 to 950) with a single accent color (Emerald #10b981) for 'Live' states. Components use sharp corners (rounded-sm) and subtle borders (#e4e4e7 / #27272a). Transitions are quick (150ms-200ms) to ensure a snappy, tool-like feel.",
    "prompt": "Create a design system using a Technical Minimalist aesthetic. \n- **Colors**: Background: #FFFFFF (Light) / #09090B (Dark). Text: #18181B (Light) / #F4F4F5 (Dark). Border: #F4F4F5 (Light) / #18181B (Dark). Accent: Emerald-500 (#10B981) for live indicators.\n- **Typography**: Headers and UI text: 'Inter', sans-serif. Monospace/Labels: 'JetBrains Mono', monospace. Sizes: H1: 64px bold, Subtitles: 20px, Section Headers: 14px uppercase with tracking-widest (0.1em), Body: 14px/16px.\n- **Borders/Corners**: Small radius (4px) or sharp corners. Border width: 1px.\n- **Animations**: Use 'cubic-bezier(0.4, 0, 0.2, 1)' for hover transitions. Include a 'ping' pulse for status dots (Emerald-400/500)."
  },
  "layout_and_structure": {
    "description": "A focused single-column layout (max-width: 768px) centered on the page. The flow is linear, starting with a bold hero and ending with a status-driven action footer.",
    "prompts": [
      {
        "part": "Header",
        "prompt": "Sticky header with 90% opacity and backdrop-blur-sm. Elements: Left-aligned logo (20px square block next to 'Superdesign' in JetBrains Mono bold). Right-aligned theme toggle using Lucide icons (Sun/Moon)."
      },
      {
        "part": "Hero Section",
        "prompt": "Large H1 'You control the AI.' (Inter, 64px, bold, tracking-tight). 20px font-medium subtext. Primary action button: Zinc-900 (Light) / White (Dark) with right-arrow icon, hover effect: scale-[0.98] on click."
      },
      {
        "part": "Configuration Sections",
