        let treeFrame = 0;
        setInterval(() => {
            treeFrame = (treeFrame + 1) % 4;
            const treeDims = getScaledTreeDimensions();
            prominentTreeElements.forEach(tree => {
                tree.style.backgroundPosition = `${-treeFrame * treeDims.width}px 0`;
