type EventType = 'thought' | 'skill_call' | 'bash_command' | 'user_message' | 'assistant_message' | 'system_event' | 'parallel_group';
type Status = 'success' | 'error' | 'pending' | 'warning' | 'running';

interface TraceEvent {
  id: string;
  turnId?: number;
  type: EventType;
  timestamp: string;
  title?: string;
  content?: string | any;
  status?: Status;
  duration?: number; // in seconds
  tokens?: number;
  agentId?: string;
  children?: TraceEvent[];
  meta?: {
    path?: string;
    repo?: string;
    url?: string;
    command?: string;
  };
}

interface SessionMetrics {
  totalDuration: number;
  totalTokens: number;
  totalCost: number;
  toolCount: number;
  agentCount: number;
  fileCount: number;
}

interface TokenUsage {
  type: string;
  tokens: number;
  cost: number | string;
}

interface ToolUsage {
  name: string;
  count: number;
}

// --- Mock Data Generator ---
