/**
 * Maternity Care App - Home Screen
 * A warm, nurturing mobile app for mothers featuring:
 * - Personalized greeting with motivational message
 * - Mood check-in with empathetic illustrations
 * - Daily self-care tracker
 * - Content exploration section
 * - Organic bottom navigation
 * 
 * Design philosophy: Soft, feminine, acolhedor (welcoming)
 */

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Home, 
  Users, 
  Heart, 
  CheckSquare,
  ChevronRight,
  Sparkles,
  Moon,
  Sun,
  Cloud,
  Flower2
} from 'lucide-react';

// Mood options with custom illustrations
const moods = [
  { 
    id: 'overwhelmed', 
    label: 'Sobrecarregada', 
    color: '#E8B4B8',
    bgGradient: 'linear-gradient(135deg, #FEE2E2 0%, #FECACA 100%)',
    icon: '💫',
    message: 'Respire fundo, você não está sozinha'
  },
  { 
    id: 'anxious', 
    label: 'Ansiosa', 
    color: '#DDA0DD',
    bgGradient: 'linear-gradient(135deg, #F3E8FF 0%, #E9D5FF 100%)',
    icon: '🌸',
    message: 'Um passo de cada vez, mamãe'
  },
  { 
    id: 'tired', 
    label: 'Exausta', 
    color: '#B4C7DC',
    bgGradient: 'linear-gradient(135deg, #E0F2FE 0%, #BAE6FD 100%)',
    icon: '🌙',
    message: 'Descanse quando puder, você merece'
  },
  { 
    id: 'stable', 
    label: 'Estável', 
    color: '#A8D5BA',
    bgGradient: 'linear-gradient(135deg, #D1FAE5 0%, #A7F3D0 100%)',
    icon: '☀️',
    message: 'Que lindo! Continue assim'
  },
];

// Custom illustration component for mood cards
const MoodIllustration: React.FC<{ mood: string; isSelected: boolean }> = ({ mood, isSelected }) => {
  const baseClass = "w-12 h-12 flex items-center justify-center text-2xl";

  return (
    <motion.div 
      className={baseClass}
      animate={{ 
        scale: isSelected ? [1, 1.1, 1] : 1,
      }}
      transition={{ 
        duration: 0.6,
        repeat: isSelected ? Infinity : 0,
        repeatType: "reverse"
      }}
    >
      {moods.find(m => m.id === mood)?.icon}
    </motion.div>
  );
};

