export type AssetStatus = 'active' | 'maintenance' | 'retired' | 'draft' | 'warning';

export interface AssetHistoryEvent {
  id: string;
  type: 'update' | 'maintenance' | 'assignment' | 'alert';
  title: string;
  description: string;
  user: string;
  date: string;
}

export interface Asset {
