            <Plus className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto space-y-4 pr-2">
          {/* Mock events for the selected date - in real app filter properly */}
          {[1, 2, 3].map((_, i) => (
