          }

          .bento-card:hover .border-glow {
            opacity: 1;
          }
        `}
      </style>

      <div ref={gridRef} className="bento-grid">
        {cardData.map((card, index) => {
          const Content = (
            <div className="bento-card h-full w-full p-6 flex flex-col justify-between group">
