      <Ribbons
        baseThickness={40}
        colors={['#1A1A1B']}
        speedMultiplier={0.5}
        maxAge={600}
        enableFade={true}
        enableShaderEffect={true}
        effectAmplitude={1.5}
      />
    </div>
  );
}
